final class MessageQueue<Element> {
    private let cond = NSCondition()
    private var items: [Element] = []

    func put(_ item: Element) {
        cond.lock()
        defer { cond.unlock() }
        while items.count == capacity { cond.wait() }   // predicate loop
        items.append(item)
        cond.broadcast()
    }
}
